 function endRound(entries,forced){if(['roundresult','results'].includes(phase))return;phase='roundresult';models.forEach(m=>m.cancel?.());const cmp=versus?forced??(entries[0].details.completed!==entries[1].details.completed?entries[0].details.completed?1:-1:game==='robot'?(entries[0].details.repairs/entries[0].details.faults-entries[1].details.repairs/entries[1].details.faults||entries[1].errors-entries[0].errors||entries[1].duration-entries[0].duration):entries[0].score-entries[1].score||entries[1].errors-entries[0].errors||entries[1].duration-entries[0].duration):0;if(versus&&cmp)wins[cmp>0?0:1]++;rounds.push(entries);if(!versus||wins.some(n=>n>=Math.ceil(series/2))||round>=series)finishMatch();else result(entries,cmp,false);}
